const lead = $json;

function randomBase36(length) {
  let out = "";
  while (out.length < length) {
    out += Math.random().toString(36).slice(2);
  }
  return out.slice(0, length).toUpperCase();
}

const now = new Date();
const datePart = now.toISOString().slice(0, 10).replace(/-/g, "");
const leadId = `LD-${datePart}-${randomBase36(4)}`;

return [
  {
    json: {
      ...lead,
      lead_id: leadId,
      last_contacted_at: "",
      next_follow_up_at: "",
      last_reminded_at: "",
      updated_at: now.toISOString()
    }
  }
];

const FOLLOWUP_STATUSES = ["CONTACTED", "QUALIFIED", "PROPOSAL"];
const now = new Date();

const dueLeads = $input.all()
  .map(i => i.json)
  .filter(lead => {
    if (!FOLLOWUP_STATUSES.includes(lead.status)) return false;
    if (!lead.next_follow_up_at) return false;

    const due = new Date(lead.next_follow_up_at);
    if (isNaN(due.getTime())) return false;
    if (due > now) return false;

    if (lead.last_reminded_at) {
      const lastReminded = new Date(lead.last_reminded_at);
      if (!isNaN(lastReminded.getTime()) && lastReminded.toDateString() === now.toDateString()) {
        return false;
      }
    }

    return true;
  });

return dueLeads.map(lead => ({ json: lead }));

