const activity = $json;

function randomBase36(length) {
  let out = "";
  while (out.length < length) {
    out += Math.random().toString(36).slice(2);
  }
  return out.slice(0, length).toUpperCase();
}

const now = new Date();
const datePart = now.toISOString().slice(0, 10).replace(/-/g, "");
const activityId = `ACT-${datePart}-${randomBase36(4)}`;

const CONTACT_TYPES = ["CONTACTED", "REPLIED", "CALL", "MEETING", "PROPOSAL_SENT", "FOLLOW_UP"];

return [{
  json: {
    ...activity,
    activity_id: activityId,
    is_contact_activity: CONTACT_TYPES.includes(activity.activity_type)
  }
}];

const now = new Date();
const ACTIVE_PIPELINE_STATUSES = ["NEW", "CONTACTED", "QUALIFIED", "PROPOSAL"];
const FOLLOWUP_STATUSES = ["CONTACTED", "QUALIFIED", "PROPOSAL"];

const rows = $input.all().map(i => i.json).filter(r => r.lead_id);

function daysBetween(dateStr, ref) {
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return null;
  return Math.floor((ref - d) / (1000 * 60 * 60 * 24));
}

let counts = { NEW: 0, CONTACTED: 0, QUALIFIED: 0, PROPOSAL: 0, WON: 0, LOST: 0, DUPLICATE: 0, INVALID: 0 };
let highPriorityCount = 0;
let overdueCount = 0;
let staleCount = 0;
let atRiskCount = 0;
let pipelineValue = 0;

for (const lead of rows) {
  if (counts.hasOwnProperty(lead.status)) counts[lead.status]++;
  if (lead.priority === "HIGH") highPriorityCount++;

  if (ACTIVE_PIPELINE_STATUSES.includes(lead.status)) {
    pipelineValue += Number(lead.budget) || 0;
  }

  // Follow-up overdue
  if (FOLLOWUP_STATUSES.includes(lead.status) && lead.next_follow_up_at) {
    const overdueDays = daysBetween(lead.next_follow_up_at, now);
    if (overdueDays !== null && overdueDays > 0) overdueCount++;
  }

  // Stale / at-risk based on last_contacted_at
  if (FOLLOWUP_STATUSES.includes(lead.status) && lead.last_contacted_at) {
    const sinceContact = daysBetween(lead.last_contacted_at, now);
    if (sinceContact !== null) {
      if (sinceContact >= 8) staleCount++;
      else if (sinceContact >= 4) atRiskCount++;
    }
  }
}

const totalLeads = rows.length;
const qualifiedOrLater = rows.filter(r => ["QUALIFIED", "PROPOSAL", "WON"].includes(r.status)).length;
const proposalOrLater = rows.filter(r => ["PROPOSAL", "WON"].includes(r.status)).length;
const won = counts.WON;

const leadToWonRate = totalLeads ? ((won / totalLeads) * 100).toFixed(1) : "0.0";
const qualifiedToWonRate = qualifiedOrLater ? ((won / qualifiedOrLater) * 100).toFixed(1) : "0.0";
const proposalToWonRate = proposalOrLater ? ((won / proposalOrLater) * 100).toFixed(1) : "0.0";

return [{
  json: {
    date: now.toISOString().slice(0, 10),
    total_leads: totalLeads,
    counts,
    high_priority_count: highPriorityCount,
    overdue_count: overdueCount,
    at_risk_count: atRiskCount,
    stale_count: staleCount,
    pipeline_value: pipelineValue,
    lead_to_won_rate: leadToWonRate,
    qualified_to_won_rate: qualifiedToWonRate,
    proposal_to_won_rate: proposalToWonRate
  }
}];

